Ext.define('BNK.view.Budget.bgx.BgxNfmAply71MItem01ViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxNfmAply71MItem01ViewController',

    config: {
        viewId: 'BgxNfmAply71MItem01'
    },

    /* 집행대상라벨 */
    fnSetSummaryUserLabel: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            expItemData = Ext.clone(vm.get('expItemData')),
            userRecords = expItemData.expItemUserInfo,
            trnsAmt = expItemData.trnsAmt,  //공급가액
            innerEmpeCnt = 0,
            outerEmpeCnt = 0,
            rtnStr = '',
            defaultStr = '승인금액',
            xpnitKeyCd = expItemData.xpnitKeyCd,
            xpnitKeyNm = expItemData.xpnitKeyNm;

        if (userRecords) {
            for (var i = 0; i < userRecords.length; i++) {
                var record = userRecords[i];
                if (record.stfDvcd == Constants.stfDvcd.IN) {
                    innerEmpeCnt++;
                } else {
                    outerEmpeCnt++;
                }
            }
            var amtByUser = (innerEmpeCnt == 0 ? 0 : Math.round(trnsAmt / innerEmpeCnt));

            rtnStr = Ext.String.format('<span style = "line-height : 20px;">집행대상 ( 총 <span style ="color : red;">{0}</span>명 ) <br>'
                                       + '[ 내부직원 {1} 명 / 외부직원 {2} 명 ] <br>'
                                       + '<span style = "color :gray;" >[{3} 기준 1인당 {4}원]</span></span>',
                                       userRecords.length, innerEmpeCnt, outerEmpeCnt, defaultStr ,
                                       amtByUser.toString().replace(/\B(?=(\d{3})+(?!\d))/g,","));

        }
        vm.set('expItemData.summaryUserLabel', rtnStr);
    },

    /* 영수증 팝업 */
    openEvidImgFilePopUp: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();

        Ext.create('BgxItmCpnt52M', {
            param : vm.get('expItemData.evidImgFileId')
        }).show();
    },

    /* 매출전표 */
    onBtnSalesSlip: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            win = Ext.create('BgxItmCpnt51M', {
                param : vm.get('expItemData')
            });

        win.show();
    },

    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            config = component.config;

        if (config) {
            vm.set('codeList', config.codeList);
            vm.set('applyInfo', config.applyInfo);
            vm.set('readOnlyFlag', config.readOnlyFlag);
            var expItemData = config.expItemData;
            vm.set('expItemData', expItemData);
            vm.set('expItemData.bsnsYy', config.applyInfo.bsnsYy);		// 2020.09.21 사업연도 추가
            vm.set('expItemInputData', expItemData);
            vm.set('expItemData.trnsYy', expItemData.trnsDt.substr(0,4));
            vm.set('infoText', config.infoText);			// 안내문구
            vm.set('record', config.record);
            vm.set('command', config.command);
            var command = config.command,
                aprHistId = config.aprHistId,
                edocCd = config.edocCd;

            // 결재문서 초기화 설정
            ApprovalBoxSvc.setup({
                command   : command,
                viewModel : vm,
                aprHistId : aprHistId,
                edocCd    : 'BgxNfmAply71',
                scope     : me
            });

            // 포매팅
            if(expItemData) {
                refs.apvlDt.setValue(DateUtils.parseDate(expItemData.apvlDt) + ' ' + expItemData.apvlHr.substr(0,2) + ':' + expItemData.apvlHr.substr(2,2) + ':' + expItemData.apvlHr.substr(4,2));
                refs.cdno.setValue(FormatUtils.cardNoFormat(expItemData.cdno, true));
                refs.canYn.setValue(CodeUtils.getText('NFC008', expItemData.canYn)); //NFC008:카드승인취소여부
                refs.trnsAmtWc.setValue(FormatUtils.moneyFormat(expItemData.trnsAmtWc)+' 원');
                refs.stxat.setValue(FormatUtils.moneyFormat(expItemData.stxat)+' 원');
                refs.apvlAmtDom.setValue(FormatUtils.moneyFormat(expItemData.apvlAmtDom)+' 원');
            }
        }

        // BgxItmCpnt31M
        var cmm = refs.common_input_container,
            cmmRefs = cmm.getReferences();

        me.fnSetSummaryUserLabel();				// 집행대상라벨
        cmmRefs.dgDsbInfoGrid.setHidden(true);  // 법인카드는 지급정보 X
        cmmRefs.imgPanel.setHidden(true);		// 사진
        // 계정과목
        cmmRefs.xpnitKeyNm.setValue(vm.get('expItemData.xpnitKeyNm'));
        cmmRefs.xpnitKeyNm.setHidden(false);
        cmmRefs.xpnitKeyCd.setHidden(true);
    }

});